Local File &report;
ZZ_RPT_AET.ZZ_RPT_TOTAL = 0;
ZZ_RPT_AET.ZZ_RPT_FILE = "record_inventory_" | String(%ProcessInstance) | ".csv";
&report = GetFile(ZZ_RPT_AET.ZZ_RPT_FILE, "W", "UTF8", %FilePath_Relative);
If Not &report.IsOpen Then
   Error ("Cannot open record inventory report.");
End-If;
&report.WriteLine("Record Type,Type Description,Definition Count");
&report.Close();

Local Record &line;
Local File &report;
Local string &label;
&line = CreateRecord(Record.ZZ_RPT_LINE);
&line.RECTYPE.Value = ZZ_RPT_AET.RECTYPE;
&line.ZZ_RPT_COUNT.Value = ZZ_RPT_AET.ZZ_RPT_COUNT;
Evaluate ZZ_RPT_AET.RECTYPE
When = 0
   &label = "SQL Table";
When = 1
   &label = "SQL View";
When = 2
   &label = "Derived Work";
When = 3
   &label = "Subrecord";
When = 5
   &label = "Dynamic View";
When = 6
   &label = "Query View";
When = 7
   &label = "Temporary Table";
When-Other
   &label = "Other";
End-Evaluate;
&line.ZZ_RPT_LABEL.Value = &label;
ZZ_RPT_AET.ZZ_RPT_TOTAL = ZZ_RPT_AET.ZZ_RPT_TOTAL + &line.ZZ_RPT_COUNT.Value;
&report = GetFile(ZZ_RPT_AET.ZZ_RPT_FILE, "A", "UTF8", %FilePath_Relative);
If Not &report.IsOpen Then
   Error ("Cannot append record inventory detail.");
End-If;
&report.WriteLine(String(&line.RECTYPE.Value) | "," | &line.ZZ_RPT_LABEL.Value | "," | String(&line.ZZ_RPT_COUNT.Value));
&report.Close();

Local Record &summary;
Local File &report;
&summary = CreateRecord(Record.ZZ_RPT_SUM);
&summary.PROCESS_INSTANCE.Value = %ProcessInstance;
&summary.ZZ_RPT_TOTAL.Value = ZZ_RPT_AET.ZZ_RPT_TOTAL;
&summary.ZZ_RPT_FILE.Value = ZZ_RPT_AET.ZZ_RPT_FILE;
&report = GetFile(&summary.ZZ_RPT_FILE.Value, "A", "UTF8", %FilePath_Relative);
If Not &report.IsOpen Then
   Error ("Cannot append record inventory total.");
End-If;
&report.WriteLine("TOTAL,All Record Definitions," | String(&summary.ZZ_RPT_TOTAL.Value));
&report.Close();
MessageBox(0, "", 0, 0, "Record inventory complete: " | &summary.ZZ_RPT_FILE.Value | "; definitions=" | String(&summary.ZZ_RPT_TOTAL.Value));
